content:
Generating Task Sequences
This page covers the main ways to create TaskSeq&lt;'T&gt; values: the taskSeq computation
expression, factory functions such as TaskSeq.init and TaskSeq.unfold, and conversion
functions that wrap existing collections.
open System.Threading.Tasks
open FSharp.Control

Computation Expression Syntax
taskSeq { ... } is a computation expression that lets you write asynchronous sequences
using familiar F# constructs.  Under the hood it compiles to a resumable state machine, so
there is no allocation per element.
Yielding values
Use yield to emit a single value and yield! to splice in another sequence:
let helloWorld = taskSeq {
    yield &quot;hello&quot;
    yield &quot;world&quot;
}

let combined = taskSeq {
    yield! helloWorld
    yield &quot;!&quot;
}

Conditionals
if/then/else works just like in ordinary F#:
let evenNumbers = taskSeq {
    for i in 1..10 do
        if i % 2 = 0 then
            yield i
}

Match expressions
match expressions are fully supported:
type Shape =
    | Circle of radius: float
    | Rectangle of width: float * height: float

let areas = taskSeq {
    for shape in [ Circle 3.0; Rectangle(4.0, 5.0); Circle 1.5 ] do
        match shape with
        | Circle r -&gt; yield System.Math.PI * r * r
        | Rectangle(w, h) -&gt; yield w * h
}

For loops
for iterates over any seq&lt;'T&gt;/IEnumerable&lt;'T&gt; synchronously, or over another
TaskSeq&lt;'T&gt; asynchronously:
let squaresOfList = taskSeq {
    for n in [ 1; 2; 3; 4; 5 ] do
        yield n * n
}

// Iterate another TaskSeq
let doubled = taskSeq {
    for n in squaresOfList do
        yield n * 2
}

While loops
while emits elements until a condition becomes false.  Async operations can appear in the
loop body:
let countdown = taskSeq {
    let mutable i = 5

    while i &gt; 0 do
        yield i
        do! Task.Delay 100
        i &lt;- i - 1
}

Awaiting tasks with let! and do!
Inside taskSeq { ... } you can await any Task&lt;'T&gt; with let! and any Task&lt;unit&gt; with
do!:
let fetchData (url: string) : Task&lt;string&gt; =
    task { return $&quot;data from {url}&quot; } // placeholder

let results = taskSeq {
    for url in [ &quot;https://example.com/a&quot;; &quot;https://example.com/b&quot; ] do
        let! data = fetchData url
        yield data
}

Use bindings and try / with
use and use! dispose the resource when the sequence finishes or is abandoned. try/with
and try/finally work as expected:
let withResource = taskSeq {
    use resource = { new System.IDisposable with member _.Dispose() = () } // placeholder
    yield 1
    yield 2
}

let withErrorHandling = taskSeq {
    try
        yield 1
        failwith &quot;oops&quot;
        yield 2
    with ex -&gt;
        yield -1
}


init and initInfinite
TaskSeq.init count initializer generates count elements by calling initializer with the
zero-based index:
// [| 0; 1; 4; 9; 16 |]
let squares : TaskSeq&lt;int&gt; = TaskSeq.init 5 (fun i -&gt; i * i)

// With an async initializer
let asyncSquares : TaskSeq&lt;int&gt; =
    TaskSeq.initAsync 5 (fun i -&gt; task { return i * i })

TaskSeq.initInfinite generates an unbounded sequence — use TaskSeq.take or
TaskSeq.takeWhile to limit consumption:
let naturals : TaskSeq&lt;int&gt; = TaskSeq.initInfinite id

let first10 : TaskSeq&lt;int&gt; = naturals |&gt; TaskSeq.take 10 // 0 .. 9


unfold
TaskSeq.unfold derives a sequence from a state value.  Each call to the generator returns
either None (end) or Some (element, nextState):
// 0, 1, 2, ... up to but not including 5
let counting : TaskSeq&lt;int&gt; =
    TaskSeq.unfold
        (fun state -&gt;
            if state &lt; 5 then
                Some(state, state + 1)
            else
                None)
        0

// Same with an async generator
let countingAsync : TaskSeq&lt;int&gt; =
    TaskSeq.unfoldAsync
        (fun state -&gt;
            task {
                if state &lt; 5 then
                    return Some(state, state + 1)
                else
                    return None
            })
        0


singleton, replicate, replicateInfinite, and empty
let one : TaskSeq&lt;string&gt; = TaskSeq.singleton &quot;hello&quot;

let fives : TaskSeq&lt;int&gt; = TaskSeq.replicate 3 5 // 5, 5, 5

let nothing : TaskSeq&lt;int&gt; = TaskSeq.empty&lt;int&gt;

TaskSeq.replicateInfinite yields a constant value indefinitely.  Always combine it with a
bounding operation such as take or takeWhile:
let infinitePings : TaskSeq&lt;string&gt; = TaskSeq.replicateInfinite &quot;ping&quot;

let first10pings : TaskSeq&lt;string&gt; = infinitePings |&gt; TaskSeq.take 10

TaskSeq.replicateInfiniteAsync calls a function on every step, useful for polling or streaming
side-effectful sources:
let mutable counter = 0

let pollingSeq : TaskSeq&lt;int&gt; =
    TaskSeq.replicateInfiniteAsync (fun () -&gt;
        task {
            counter &lt;- counter + 1
            return counter
        })

let first5counts : TaskSeq&lt;int&gt; = pollingSeq |&gt; TaskSeq.take 5

TaskSeq.replicateUntilNoneAsync stops when the function returns None, making it easy to
wrap a pull-based source that signals end-of-stream with None:
let readLine (reader: System.IO.TextReader) =
    TaskSeq.replicateUntilNoneAsync (fun () -&gt;
        task {
            let! line = reader.ReadLineAsync()
            return if line = null then None else Some line
        })


delay
TaskSeq.delay creates a sequence whose body is not evaluated until iteration starts.  This
is useful when the sequence depends on side-effectful initialisation:
let deferred =
    TaskSeq.delay (fun () -&gt;
        taskSeq {
            printfn &quot;sequence started&quot;
            yield! [ 1; 2; 3 ]
        })


Converting from existing collections
All of these produce a TaskSeq&lt;'T&gt; that replays the source on each iteration:
let fromArray : TaskSeq&lt;int&gt; = TaskSeq.ofArray [| 1; 2; 3 |]
let fromList : TaskSeq&lt;int&gt; = TaskSeq.ofList [ 1; 2; 3 ]
let fromSeq : TaskSeq&lt;int&gt; = TaskSeq.ofSeq (seq { 1..3 })
let fromResizeArray : TaskSeq&lt;int&gt; = TaskSeq.ofResizeArray (System.Collections.Generic.List&lt;int&gt;([ 1; 2; 3 ]))

You can also wrap existing task or async collections.  Note that wrapping a list of already
started Tasks does not guarantee sequential execution—the tasks are already running:
// Sequence of not-yet-started task factories (safe)
let fromTaskSeq : TaskSeq&lt;int&gt; =
    TaskSeq.ofTaskSeq (seq { yield task { return 1 }; yield task { return 2 } })

// Sequence of asyncs (each started on demand as the sequence is consumed)
let fromAsyncSeq : TaskSeq&lt;int&gt; =
    TaskSeq.ofAsyncSeq (seq { yield async { return 1 }; yield async { return 2 } })

Transforming Task Sequences
This page covers the core operations for transforming TaskSeq&lt;'T&gt; values: map, filter,
choose, collect, indexed, and type conversions.
For operations that consume a sequence into a single result, see
Consuming Sequences.
open System.Threading.Tasks
open FSharp.Control

Transforming with a computation expression
The most flexible way to transform a task sequence is to write a function that accepts a
TaskSeq&lt;_&gt; and returns a TaskSeq&lt;_&gt; using a taskSeq { ... } computation expression. The
for loop inside the CE is an asynchronous loop that awaits each element:
let labelEvenOdd (input: TaskSeq&lt;int&gt;) : TaskSeq&lt;string&gt; =
    taskSeq {
        for n in input do
            if n % 2 = 0 then
                do! Task.Delay 10 // simulate async work
                yield $&quot;Even: {n}&quot;
            else
                yield $&quot;Odd: {n}&quot;
    }

Inside taskSeq { ... } you can freely mix synchronous logic, let!/do! awaits, loops,
and conditionals.

map and mapAsync
TaskSeq.map applies a synchronous function to every element:
let numbers : TaskSeq&lt;int&gt; = TaskSeq.ofSeq (seq { 1..5 })

let doubled : TaskSeq&lt;int&gt; = numbers |&gt; TaskSeq.map (fun n -&gt; n * 2)

TaskSeq.mapAsync is the same but the projection returns Task&lt;'U&gt;, allowing async work per
element — for example, a database lookup or HTTP request:
let fetchDescription (n: int) : Task&lt;string&gt; =
    task { return $&quot;item {n}&quot; } // placeholder for a real async call

let descriptions : TaskSeq&lt;string&gt; = numbers |&gt; TaskSeq.mapAsync fetchDescription

mapi and mapiAsync
TaskSeq.mapi and TaskSeq.mapiAsync additionally pass the zero-based index to the mapper:
let indexed : TaskSeq&lt;string&gt; =
    numbers |&gt; TaskSeq.mapi (fun i n -&gt; $&quot;[{i}] {n}&quot;)


filter and filterAsync
TaskSeq.filter keeps only elements satisfying a synchronous predicate:
let evens : TaskSeq&lt;int&gt; = numbers |&gt; TaskSeq.filter (fun n -&gt; n % 2 = 0)

TaskSeq.filterAsync does the same with an async predicate — useful when the keep/discard
decision requires an async lookup:
let isInteresting (n: int) : Task&lt;bool&gt; =
    task { return n &gt; 2 } // placeholder

let interesting : TaskSeq&lt;int&gt; = numbers |&gt; TaskSeq.filterAsync isInteresting

TaskSeq.where and TaskSeq.whereAsync are aliases for filter and filterAsync provided
for readability.

choose and chooseAsync
TaskSeq.choose applies a function that returns 'U option; only Some values are kept and
the option wrapper is removed — it is equivalent to filter + map in a single pass:
let strings : TaskSeq&lt;string&gt; =
    TaskSeq.ofList [ &quot;&quot;; &quot;hello&quot;; &quot;&quot;; &quot;world&quot; ]

let nonEmpty : TaskSeq&lt;string&gt; =
    strings
    |&gt; TaskSeq.choose (fun s -&gt;
        if s.Length &gt; 0 then Some s else None)

TaskSeq.chooseAsync accepts an async chooser:
let parseAsync (s: string) : Task&lt;int option&gt; =
    task {
        match System.Int32.TryParse s with
        | true, n -&gt; return Some n
        | _ -&gt; return None
    }

let parsed : TaskSeq&lt;int&gt; =
    TaskSeq.ofList [ &quot;1&quot;; &quot;two&quot;; &quot;3&quot; ]
    |&gt; TaskSeq.chooseAsync parseAsync


collect and collectSeq
TaskSeq.collect is the monadic bind for TaskSeq: it maps each element to a new task
sequence and concatenates all the results end-to-end:
let words : TaskSeq&lt;string&gt; =
    TaskSeq.ofList [ &quot;foo bar&quot;; &quot;baz qux&quot; ]

let chars : TaskSeq&lt;string&gt; =
    words
    |&gt; TaskSeq.collectSeq (fun sentence -&gt;
        sentence.Split(&#39; &#39;) |&gt; Array.toSeq)

TaskSeq.collect maps to another TaskSeq&lt;'U&gt;, while TaskSeq.collectSeq maps to a plain
seq&lt;'U&gt;. Async variants TaskSeq.collectAsync and TaskSeq.collectSeqAsync accept mappers
that return tasks.

indexed
TaskSeq.indexed pairs each element with its zero-based index, returning a
TaskSeq&lt;int * 'T&gt;:
let withIndex : TaskSeq&lt;int * string&gt; =
    TaskSeq.ofList [ &quot;a&quot;; &quot;b&quot;; &quot;c&quot; ] |&gt; TaskSeq.indexed

// yields (0,&quot;a&quot;), (1,&quot;b&quot;), (2,&quot;c&quot;)


Type conversions
TaskSeq.cast casts items from TaskSeq&lt;obj&gt; to a target reference type. For value types use
TaskSeq.unbox:
let boxed : TaskSeq&lt;obj&gt; =
    TaskSeq.ofList [ box 1; box 2; box 3 ]

let unboxed : TaskSeq&lt;int&gt; = boxed |&gt; TaskSeq.unbox&lt;int&gt;

let castToString : TaskSeq&lt;string&gt; =
    TaskSeq.ofList [ box &quot;hello&quot;; box &quot;world&quot; ]
    |&gt; TaskSeq.cast&lt;string&gt;
